class Solution {
public:
    bool validateStackSequences(vector<int>& pushed, vector<int>& popped) {
        vector<int> st;
        int j = 0;
        for (int x : pushed) {
            st.push_back(x);
            while (!st.empty() && j < (int)popped.size() && st.back() == popped[j]) {
                st.pop_back();
                j++;
            }
        }
        return j == (int)popped.size();
    }
};

class Solution {
    public boolean validateStackSequences(int[] pushed, int[] popped) {
        int[] st = new int[pushed.length];
        int top = 0, j = 0;
        for (int x : pushed) {
            st[top++] = x;
            while (top > 0 && j < popped.length && st[top - 1] == popped[j]) {
                top--;
                j++;
            }
        }
        return j == popped.length;
    }
}

var validateStackSequences = function(pushed, popped) {
    const st = [];
    let j = 0;
    for (let i = 0; i < pushed.length; i++) {
        st.push(pushed[i]);
        while (st.length > 0 && j < popped.length && st[st.length - 1] === popped[j]) {
            st.pop();
            j++;
        }
    }
    return j === popped.length;
};
